	/**
	 * Tests with standard tone marks, no surname mode.
	 * Summary TestStandardNoSurnames: 41.467065868263475%  words (277 of 668), 98.88372093023256% syllables (1063 of 1075)
	 */
	@Nested
	public class TestStandardNoSurnames extends ConversionQualityOfNamesTestBase {
		
		@Override
		protected PinyinToneMode getToneMode() {
			return PinyinToneMode.STANDARD;
		}
		
		@Override
		protected SurnameMode getSurnameMode() {
			return SurnameMode.OFF;
		}
		
		@Override
		protected double expectedSyllableMatchPercent() {
			return 98.0;
		}
		
		@Override
		protected double expectedWordMatchPercent() {
			return 40.0;
		}
		
	}
	
