	public static abstract class ConversionQualityOfNamesTestBase extends ConversionQualityTestBase {
		
		@Test
		public void testNames() {
			
			String[] inputNames = ZH_NAMES.split("\n");
			String[] expectedNames = GOOGLE_PINYIN.split("\n");
			
			int index = 0;
			MatchInfo all = new MatchInfo();
			for (String name : inputNames) {
				String zh = name.trim();
				String expected = expectedNames[index].trim();
				index++;
				
				MatchInfo partInfo = match(zh, expected);
				all.add(partInfo);
				System.out.println();
			}
			
			System.out.println(
					"Summary " + (getClass().getSimpleName()) + ": "
							+ all.percentWordMatch() + "%  words (" + all.wordMatchCount + " of " + all.wordCountTested
							+ " tested words (" + all.wordCountReference + " reference words)), "
							+ all.percentSyllableMatch() + "% syllables (" + all.syllableMatchCount + " of "
							+ all.syllableCount + ")");
			
			assertTrue(all.percentWordMatch() > expectedWordMatchPercent(), "Word match percent too low");
			assertTrue(all.percentSyllableMatch() > expectedSyllableMatchPercent(), "Syllable match percent too low");
		}
		
		protected abstract double expectedSyllableMatchPercent();
		
		protected abstract double expectedWordMatchPercent();
		
	}
